CREATE OR ALTER PROCEDURE [dbo].[uspStandardCost_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @DishId UNIQUEIDENTIFIER = NULL
	, @RecipeId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CostPerServing DECIMAL(18,4) = NULL
	, @EffectiveFrom DATETIME = NULL
	, @EffectiveTo DATETIME = NULL
	, @CurrencyCode NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[DishId]
			, j1.[Name] AS [DishName]
			, t.[RecipeId]
			, t.[MaterialCost]
			, t.[LaborCost]
			, t.[OverheadCost]
			, t.[TotalCost]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[CostPerServing]
			, t.[CurrencyCode]
			, t.[CreatedDate]
		FROM [dbo].[StandardCost] AS t
		LEFT JOIN [dbo].[Dishe] AS j1 ON j1.[Id] = t.[DishId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[CurrencyCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@DishId IS NULL OR t.[DishId] = @DishId)
			AND (@RecipeId IS NULL OR t.[RecipeId] = @RecipeId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CostPerServing IS NULL OR t.[CostPerServing] = @CostPerServing)
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND (ISNULL(@CurrencyCode, '') = '' OR t.[CurrencyCode] LIKE CONCAT('%', @CurrencyCode, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishId' THEN r.[DishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishId' THEN r.[DishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishName' THEN r.[DishName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishName' THEN r.[DishName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recipeId' THEN r.[RecipeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recipeId' THEN r.[RecipeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'materialCost' THEN r.[MaterialCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialCost' THEN r.[MaterialCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'laborCost' THEN r.[LaborCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'laborCost' THEN r.[LaborCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'overheadCost' THEN r.[OverheadCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'overheadCost' THEN r.[OverheadCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'totalCost' THEN r.[TotalCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'totalCost' THEN r.[TotalCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'costPerServing' THEN r.[CostPerServing] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'costPerServing' THEN r.[CostPerServing] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
